#!/usr/bin/env node
/** Length + uniqueness pads for 2026-10-06. Re-run apply is skipped; patch lib files. */
const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");

function replaceField(src, id, key, value) {
  const idTok = `id: "${id}"`;
  const idx = src.indexOf(idTok);
  if (idx < 0) throw new Error("missing " + id);
  const start = src.lastIndexOf("  {", idx);
  const next = src.indexOf("\n  },", idx);
  if (start < 0 || next < 0) throw new Error("block " + id);
  let block = src.slice(start, next + 5);
  const re = new RegExp(`(${key}: )"[\\s\\S]*?"`);
  // naive: key is JSON string on one line from apply
  const lineRe = new RegExp(`    ${key}: "[\\\\s\\\\S]*?",`);
  const keyIdx = block.indexOf(`    ${key}: `);
  if (keyIdx < 0) throw new Error(id + " " + key);
  let i = keyIdx + (`    ${key}: `).length;
  if (block[i] !== '"') throw new Error(id + " " + key + " not string");
  i++;
  let out = "";
  while (i < block.length) {
    if (block[i] === "\\") {
      out += block[i] + block[i + 1];
      i += 2;
      continue;
    }
    if (block[i] === '"') break;
    out += block[i++];
  }
  const endQuote = i;
  const newVal = JSON.stringify(value);
  block = block.slice(0, keyIdx) + `    ${key}: ${newVal},` + block.slice(endQuote + 2);
  return src.slice(0, start) + block + src.slice(next + 5);
}

function inject(body, moreAdd, houseAdd) {
  let b = body;
  if (moreAdd) {
    b = b.replace("\n\n■ 기관·하우스 뷰", "\n\n" + moreAdd.trim() + "\n\n■ 기관·하우스 뷰");
  }
  if (houseAdd) {
    b = b.replace(
      "\n\ninvestus.kr SRP 최고투자책임자 발행",
      "\n\n" + houseAdd.trim() + "\n\ninvestus.kr SRP 최고투자책임자 발행",
    );
  }
  return b;
}

function extractField(src, id, key) {
  const idTok = `id: "${id}"`;
  const idx = src.indexOf(idTok);
  const start = src.lastIndexOf("  {", idx);
  const next = src.indexOf("\n  },", idx);
  const block = src.slice(start, next + 5);
  const keyIdx = block.indexOf(`    ${key}: `);
  let i = keyIdx + (`    ${key}: `).length;
  if (block[i] !== '"') return "";
  i++;
  let out = "";
  while (i < block.length) {
    if (block[i] === "\\") {
      const n = block[i + 1];
      if (n === "n") out += "\n";
      else if (n === "t") out += "\t";
      else if (n === '"') out += '"';
      else if (n === "\\") out += "\\";
      else out += n;
      i += 2;
      continue;
    }
    if (block[i] === '"') break;
    out += block[i++];
  }
  return out;
}

